### FUNCION: createCardElement(card)
```js
function createCardElement(card) {
    const cardEl = document.createElement('div');
    cardEl.className = 'card';
    cardEl.setAttribute('data-id', card.id);

    // Drag Handle (R6)
    const handle = document.createElement('button');
    handle.className = 'drag-handle';
    handle.innerHTML = '&#x2195;'; // Icono de agarre
    cardEl.appendChild(handle);

    // Card Body
    const body = document.createElement('div');
    body.className = 'card-body';

    // Title
    const title = document.createElement('div');
    title.className = 'card-title';
    title.textContent = card.title;
    body.appendChild(title);

    // Description
    if (card.description) {
        const description = document.createElement('div');
        description.className = 'card-description';
        description.textContent = card.description;
        body.appendChild(description);
    }

    // Priority Tag
    if (card.priority) {
        const tag = document.createElement('span');
        tag.className = `priority-tag priority-${card.priority}`;
        tag.textContent = card.priority.toUpperCase();
        body.appendChild(tag);
    }

    // Actions Buttons (R14, R17)
    const actionsContainer = document.createElement('div');
    actionsContainer.className = 'card-actions';

    if (card.isEditable) {
        const editBtn = document.createElement('button');
        editBtn.className = 'action-btn';
        editBtn.innerHTML = '✏️';
        editBtn.onclick = () => openModal('edit', card.id);
        actionsContainer.appendChild(editBtn);
    }

    if (card.isDeletable) {
        const deleteBtn = document.createElement('button');
        deleteBtn.className = 'action-btn';
        deleteBtn.innerHTML = '🗑️';
        deleteBtn.onclick = () => confirmDelete(card.id);
        actionsContainer.appendChild(deleteBtn);
    }

    body.appendChild(actionsContainer);
    cardEl.appendChild(body);

    // Add event listeners for drag and drop
    handleDragStart(event, card.id);
    return cardEl;
}
